                    i += 1
                else:
                    break
            out.append(".".join(grp) + ".")
            continue
        elif wl in PARTICLES and len(out) > 0:
            out.append(wl)
        elif wl in SUFFIX_ROMAN:
            out.append(wl.upper())
        elif wl in ("jr","sr"):
